-- A FIXTURE tree shaped like CPython (cartograph.cpython): `PyObject *` a pointer slot, the fast-call function type
-- (`PyObject *const *args, Py_ssize_t nargs`, parameters unnamed), METH_ flags, a PyMethodDef table owned by a
-- PyModuleDef, an exception store and a NULL-returning error helper. No library is built: the representatives (a
-- linked probe) are a GAP here, every other fact the tree's. Shared by cpython_spec: dofile it for FILES.
local FILES = {
    ['Python.h'] = table.concat({
        '#ifndef PYTHON_H', '#define PYTHON_H', '#include <stddef.h>',
        'typedef long Py_ssize_t;',
        'typedef struct _typeobject PyTypeObject;',
        'typedef struct _object { Py_ssize_t ob_refcnt; PyTypeObject *ob_type; } PyObject;',
        'struct _typeobject { PyObject ob_base; const char *tp_name; unsigned long tp_flags; };',
        'typedef struct _ts { PyObject *current_exception; } PyThreadState;',
        'typedef PyObject *(*PyCFunction)(PyObject *, PyObject *);',
        'typedef PyObject *(*_PyCFunctionFast) (PyObject *, PyObject *const *, Py_ssize_t);',
        'typedef struct PyMethodDef { const char *ml_name; PyCFunction ml_meth; int ml_flags; const char *ml_doc; } PyMethodDef;',
        'typedef struct PyModuleDef { int m_base; const char *m_name; const char *m_doc; Py_ssize_t m_size; PyMethodDef *m_methods; } PyModuleDef;',
        '#define METH_VARARGS  0x0001', '#define METH_KEYWORDS 0x0002', '#define METH_NOARGS   0x0004', '#define METH_O        0x0008',
        '#define METH_FASTCALL  0x0080',
        '#define _PyCFunction_CAST(func) ((PyCFunction)(void(*)(void))(func))',
        'extern PyTypeObject PyUnicode_Type;',
        'static inline PyTypeObject *Py_TYPE(PyObject *ob) { return ob->ob_type; }',
        'void _PyErr_SetRaisedException(PyThreadState *tstate, PyObject *exc);',
        'PyObject *PyErr_Format(PyObject *exception, const char *format, ...);',
        '#endif',
    }, '\n') .. '\n',
    ['errors.c'] = table.concat({
        '#include "Python.h"',
        'static PyThreadState the_ts;',
        'void _PyErr_SetRaisedException(PyThreadState *tstate, PyObject *exc)',
        '{',
        '    tstate->current_exception = exc;',
        '}',
        'PyObject *PyErr_Format(PyObject *exception, const char *format, ...)',
        '{',
        '    _PyErr_SetRaisedException(&the_ts, exception);',
        '    return NULL;',
        '}',
    }, '\n') .. '\n',
    ['bltinmodule.c'] = table.concat({
        '#include "Python.h"',
        'static PyObject *builtin_len(PyObject *module, PyObject *obj)',
        '{',
        '    if (Py_TYPE(obj) != &PyUnicode_Type)',
        '        return PyErr_Format(NULL, "no len()");',
        '    return obj;',
        '}',
        'static PyObject *builtin_hasattr(PyObject *module, PyObject *const *args, Py_ssize_t nargs)',
        '{',
        '    if ((nargs) && (nargs) < 2)',
        '        return PyErr_Format(NULL, "hasattr expected 2 arguments");',
        '    return args[0];',
        '}',
        'static PyMethodDef builtin_methods[] = {',
        '    {"len", (PyCFunction)builtin_len, METH_O, NULL},',
        '    {"hasattr", _PyCFunction_CAST(builtin_hasattr), METH_FASTCALL, NULL},',
        '    {NULL, NULL}',
        '};',
        'static struct PyModuleDef builtinsmodule = { 0, "builtins", NULL, -1, builtin_methods };',
        'PyModuleDef *builtins_def(void) { return &builtinsmodule; }',
    }, '\n') .. '\n',
}
return FILES
